(()=>{'use strict';const desired=window.__BOOM_SCHEMA;if(!Array.isArray(desired)||!desired.length)return;const initialPath=location.pathname;let pending=false;function apply(){const text=JSON.stringify({'@context':'https://schema.org','@graph':window.__BOOM_SCHEMA||desired});pending=false;if(location.pathname!==initialPath){location.reload();return;}let own=document.querySelector('script[data-boom-authoritative]');if(!own){own=document.createElement('script');own.type='application/ld+json';own.dataset.boomAuthoritative='1';own.textContent=text;document.head.append(own)}else if(own.textContent!==text)own.textContent=text;for(const script of document.querySelectorAll('script[type="application/ld+json"]'))if(script!==own)script.remove()}const observer=new MutationObserver(()=>{if(!pending){pending=true;setTimeout(apply,40)}});observer.observe(document.head,{childList:true,subtree:true,characterData:true});apply();window.addEventListener('popstate',()=>{location.reload()});})();
